import Foundation

/// Short forms of given names, and the names they stand for.
///
/// Derived from the public `carltonnorthern/nicknames` dataset — 2,823 pairs covering
/// 1,423 short forms. It replaced a table of about thirty that I wrote from memory, and
/// the swap was worth making for one measured reason: **41% of real nicknames stand for
/// more than one formal name.** "Jo" is short for Joan, Joann, Joanna, Joanne, Jocelyn
/// *and* Jody. A table that maps each nickname to a single name — as mine did — is
/// silently wrong two times in five, and wrong in the direction that merges people.
///
/// So the mapping is one-to-many, and expansion runs in one direction only: a nickname
/// may match the formal name it stands for, never another nickname of the same name.
/// Without that rule "Bob" and "Bert" would be the same person, since both are short for
/// Robert. Where a short form fits several names at once, the ladder's uniqueness rule
/// does the rest — it matches only while exactly one of them is in the library.
public enum Nicknames {
    /// nickname → the formal names it can stand for.
    public static let formalNames: [String: Set<String>] = {
        var table: [String: Set<String>] = [:]
        table.reserveCapacity(1423)
        for entry in packed.split(separator: ";") {
            let parts = entry.split(separator: ":", maxSplits: 1)
            guard parts.count == 2 else { continue }
            table[String(parts[0])] = Set(parts[1].split(separator: ",").map(String.init))
        }
        return table
    }()

    /// Whether `short` is a recognised short form of `full`. One direction only.
    public static func stands(_ short: String, for full: String) -> Bool {
        formalNames[short]?.contains(full) ?? false
    }

